<script lang="ts" setup>
import type { CaseRule } from '../types';
const props = defineProps<{ rules: CaseRule[] }>();
const emit = defineEmits<{ add: []; remove: [id: string]; update: [rule: CaseRule] }>();
const typeText = { main: '主路径', delay: '延误分支', safety: '严重安全事件' };
const transitionText = { stayCurrentStage: '留在当前阶段', nextCycle: '进入下一 CPR 周期', nextStage: '进入下一阶段', instructorIntervention: '导师介入', debriefExit: '复盘出口' };
function editName(rule: CaseRule) { const name = window.prompt('规则名称', rule.name); if (name?.trim()) emit('update', { ...rule, name: name.trim() }); }
</script>
<template>
  <div><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><p class="text-sm text-muted-foreground">每条规则支持多个 AND / OR 条件组合；复杂情景应拆为可审核的单一临床意图规则。</p><button class="btn-primary" @click="emit('add')">＋ 添加规则</button></div><div class="space-y-3"><article v-for="rule in props.rules" :key="rule.id" class="rule-card" :class="`rule-${rule.type}`"><div class="flex flex-wrap items-start justify-between gap-3"><div><span class="rule-label">{{ typeText[rule.type] }}</span><h3 class="mt-2 font-semibold">{{ rule.name }}</h3><p class="mt-1 text-sm text-muted-foreground">条件组：{{ rule.conditionLogic === 'all' ? '全部满足（AND）' : '任一满足（OR）' }} · {{ rule.conditions.length }} 项条件 · 时限 {{ rule.deadlineSeconds }} 秒</p><p class="mt-2 text-sm"><b>条件：</b>{{ rule.conditions.map((item) => `${item.field} ${item.operator} ${item.value}`).join('；') }}</p><p class="mt-1 text-sm"><b>后果：</b>{{ rule.effects.join('、') }}；{{ transitionText[rule.transition] }}；评分 {{ rule.scoreChange > 0 ? '+' : '' }}{{ rule.scoreChange }}</p></div><div class="flex gap-3 text-sm"><button class="text-primary hover:underline" @click="editName(rule)">编辑名称</button><button class="text-red-600 hover:underline" @click="emit('remove', rule.id)">删除</button></div></div></article><p v-if="!props.rules.length" class="rounded-lg border border-dashed border-border py-10 text-center text-sm text-muted-foreground">尚未配置规则</p></div></div>
</template>
<style scoped>.btn-primary { @apply rounded-md bg-primary px-3 py-2 text-sm font-medium text-primary-foreground; }.rule-card { @apply rounded-lg border border-border border-l-4 bg-card p-4; }.rule-main { @apply border-l-emerald-500; }.rule-delay { @apply border-l-amber-500; }.rule-safety { @apply border-l-red-500; }.rule-label { @apply rounded bg-muted px-2 py-0.5 text-xs font-medium; }.rule-main .rule-label { @apply bg-emerald-100 text-emerald-700; }.rule-delay .rule-label { @apply bg-amber-100 text-amber-700; }.rule-safety .rule-label { @apply bg-red-100 text-red-700; }</style>